sys_script_fix.script:
if (!pm.isZboot()) {
    var gr = new GlideRecord('par_coreui_migration_bridge_dashboard');
    gr.query();
    while (gr.next()) {
        if (gr.getValue('pa_dashboard'))
            SNC.MigrationServiceScriptable.migrateDashboardLevelGroupPermissions(gr.getValue('pa_dashboard'));
    }
}
